const {chromium}=require(process.env.ADC_PLAYWRIGHT_MODULE||'playwright');
const path=require('node:path');
const output=path.resolve(__dirname,'../../../../work');
const [base,id]=process.argv.slice(2);
(async()=>{
 const browser=await chromium.launch({headless:true});
 try{
  const context=await browser.newContext({viewport:{width:1440,height:1000}});
  const page=await context.newPage();
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto(base+'/login');await page.getByLabel('Username',{exact:true}).fill('fixture');await page.getByLabel('Password',{exact:true}).fill('ui-fixture-password');await page.getByRole('button',{name:'Sign in'}).click();
  await page.getByRole('link',{name:/1 work proposal to consider/}).click();
  await page.getByRole('heading',{name:'Work worth considering.'}).waitFor();
  await page.getByRole('button',{name:'Ask for proposals',exact:true}).click();
  await page.getByLabel('Your brief',{exact:true}).fill('Unsubmitted proposal request');
  await page.request.get(base+'/fixture-proposal-add');await page.getByRole('heading',{name:'Fixture deferred proposal',exact:true}).waitFor();
  if(await page.getByLabel('Your brief',{exact:true}).inputValue()!=='Unsubmitted proposal request')throw Error('Queue update erased proposal request');
  await page.getByRole('button',{name:'Close',exact:true}).click();
  await page.screenshot({path:path.join(output,'ui-proposals-queue.png'),fullPage:true});
  await page.getByRole('link',{name:/Inspect storage recovery coverage/}).click();
  await page.getByRole('heading',{name:'Inspect storage recovery coverage',exact:true}).waitFor();
  await page.screenshot({path:path.join(output,'ui-proposal-desktop.png'),fullPage:true});
  const stale=await page.context().newPage();await stale.goto(base+`/proposal?org=org&id=${id}`);
  await page.getByText('Edit proposal',{exact:true}).click();
  const edit=page.locator('form').filter({has:page.locator('input[value="edit"]')});
  await edit.locator('textarea[name=scope]').fill('Read-only inspection of the backup catalog. No restore actions.');
  await edit.getByRole('button',{name:'Save revision'}).click();
  await page.getByText(/PROPOSED WORK · pending · REVISION 2/).waitFor();
  await stale.getByText('Accept & start work',{exact:true}).click();
  const oldAccept=stale.locator('form').filter({has:stale.locator('input[value="accept"]')});
  await oldAccept.getByLabel('Your subscription',{exact:true}).selectOption('account');await oldAccept.getByLabel('Authority for this assignment').selectOption('observe');await oldAccept.getByRole('button',{name:'Accept and start assignment'}).click();
  await stale.getByRole('alert').getByText(/this proposal changed/).waitFor();await stale.close();
  await page.getByText('Discuss with the agent',{exact:true}).click();
  const discussion=page.locator('form').filter({has:page.locator('input[value="discuss"]')});
  await discussion.getByLabel('Question or requested revision').fill('Can we keep this read-only?');await discussion.getByLabel('Subscription for this conversation').selectOption('account');await discussion.getByRole('button',{name:'Send for discussion'}).click();
  await page.getByText('Can we keep this read-only?',{exact:true}).waitFor();
  await page.getByText('Edit proposal',{exact:true}).click();
  const editing=page.locator('form').filter({has:page.locator('input[value="edit"]')});await editing.getByLabel('Title',{exact:true}).fill('Unsubmitted human edit');
  await page.request.get(base+'/fixture-proposal-reply');await page.getByText('Fixture reply: keep the inspection read-only and report unknowns.',{exact:true}).waitFor();
  if(await editing.getByLabel('Title',{exact:true}).inputValue()!=='Unsubmitted human edit')throw Error('Discussion update erased edit');
  await page.getByText('Edit proposal',{exact:true}).click();
  await page.setViewportSize({width:390,height:844});
  if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Proposal page overflows phone');
  await page.screenshot({path:path.join(output,'ui-proposal-mobile.png'),fullPage:true});
  await page.getByText('Accept & start work',{exact:true}).click();
  const accept=page.locator('form').filter({has:page.locator('input[value="accept"]')});
  await accept.getByLabel('Your subscription',{exact:true}).selectOption('account');await accept.getByLabel('Authority for this assignment').selectOption('observe');await accept.getByRole('button',{name:'Accept and start assignment'}).click();
  await page.waitForURL(/\/task\?/);await page.getByRole('heading',{name:'Inspect storage recovery coverage',exact:true}).waitFor();
  await page.goto(base+`/proposal?org=org&id=${id}`);await page.getByRole('link',{name:/This proposal became an assignment/}).waitFor();
  if(await page.getByText('Accept & start work',{exact:true}).count())throw Error('Accepted proposal still actionable');
  if(errors.length)throw Error(errors.join('\n'));
  console.log(JSON.stringify({queue:true,liveQueuePreservesForm:true,edit:true,staleApprovalRejected:true,discussionWithoutAcceptance:true,liveReplyPreservesForm:true,mobileOverflow:false,acceptance:true,browserErrors:errors}));
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
